# Code generated by workcell-hostutil adapters gen from adapters/*/adapter.toml. DO NOT EDIT.

# workcell_supported_agent succeeds when $1 is a supported adapter id.
workcell_supported_agent() {
  case "$1" in
    claude | codex | copilot | gemini) ;;
    *)
      return 1
      ;;
  esac
}

# workcell_adapter_tier prints the manifest tier of supported adapter $1.
workcell_adapter_tier() {
  case "$1" in
    claude | codex | copilot | gemini)
      echo certified
      ;;
    *)
      return 1
      ;;
  esac
}

# workcell_manifest_flags prints the [flags] list $2 (allow, deny, or
# other_commands) of uncertified adapter $1, one entry per line.
workcell_manifest_flags() {
  case "$1:$2" in
    *)
      return 1
      ;;
  esac
}
